const UCC_VERSION = "2.2.0";
const UCC_VOLVO_FONT = "data:font/woff2;base64,";

const UCC_DEFAULT_LABELS = {
  locked: "Locked",
  unlocked: "Unlocked",
  charging: "Charging",
  connected: "Connected",
  disconnected: "Disconnected",
  parked: "Parked",
  range: "Range",
  electric: "Electric",
  fuel: "Fuel",
  battery: "Battery",
  odometer: "Odometer",
  lock: "Lock",
  unlock: "Unlock",
  more: "More",
  unavailable: "Unavailable",
};

function uccImagePosition(styles, key) {
  const image = styles?.[key] || {};
  const clamp = (value, fallback, min, max) => {
    const number = Number(value ?? fallback);
    return Number.isFinite(number) ? Math.min(max, Math.max(min, number)) : fallback;
  };
  return {
    scale: clamp(image.scale ?? styles?.image_scale, 1, 0.5, 4),
    x: clamp(image.x ?? styles?.image_offset_x, 0, -100, 100),
    y: clamp(image.y, 0, -100, 100),
  };
}

class UniversalCarCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._hass = null;
    this._config = null;
    this._dialogOpen = false;
    this._manualImageKey = null;
    this._lastRenderSignature = "";
    this._imageChecks = new Map();
    this._previewConnected = null;
  }

  static getConfigElement() {
    return document.createElement("universal-car-card-editor");
  }

  static getStubConfig() {
    return {
      type: "custom:universal-car-card",
      vehicle: { make: "", model: "" },
      entities: {},
      images: {},
    };
  }

  setConfig(config) {
    if (!config) throw new Error("Card configuration is missing.");
    this._config = this._normalizeConfig(config);
    this._manualImageKey = null;
    this._render(true);
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  // Used only by the two read-only previews inside the visual editor.
  setPreviewConnected(connected) {
    this._previewConnected = connected;
    if (this._config) this._render(true);
  }

  getCardSize() {
    // Masonry uses roughly 50 px per size unit; the card is square.
    const width = this.getBoundingClientRect?.().width || 400;
    return Math.max(3, Math.ceil(width / 50));
  }

  getGridOptions() {
    return {
      columns: 12,
      min_columns: 6,
    };
  }

  _normalizeConfig(config) {
    const vehicle = config.vehicle || {};
    const display = config.display || {};
    return {
      ...config,
      vehicle: {
        make: vehicle.make ?? config.make ?? "",
        model: vehicle.model ?? config.model ?? "",
        trim: vehicle.trim ?? "",
        name: vehicle.name ?? config.name ?? vehicle.model ?? "Car",
      },
      entities: config.entities || {},
      images: config.images || {},
      display: {
        image_mode: display.image_mode ?? "auto",
        image_fit: display.image_fit ?? "contain",
        show_brand: display.show_brand ?? true,
        show_model: display.show_model ?? true,
        show_trim: display.show_trim ?? true,
        show_odometer: display.show_odometer ?? true,
        show_image_switcher: display.show_image_switcher ?? false,
        show_action_button: display.show_action_button ?? true,
        compact: display.compact ?? false,
      },
      labels: { ...UCC_DEFAULT_LABELS, ...(config.labels || {}) },
      units: config.units || {},
      styles: config.styles || {},
      actions: config.actions || {},
    };
  }

  _entity(ref) {
    if (!this._hass || !ref || typeof ref !== "string") return null;
    return this._hass.states?.[ref] || null;
  }

  _state(ref) {
    return this._entity(ref)?.state;
  }

  _attr(ref, attr) {
    return this._entity(ref)?.attributes?.[attr];
  }

  _isUnavailableValue(value) {
    return value === undefined || value === null || value === "" ||
      ["unknown", "unavailable", "none", "null"].includes(String(value).toLowerCase());
  }

  _isTruthyState(value) {
    if (this._isUnavailableValue(value)) return false;
    return [
      "on", "true", "yes", "connected", "plugged", "plugged_in",
      "connected_ac", "connected_dc", "charging", "ready", "active"
    ].includes(String(value).toLowerCase());
  }

  _isCharging() {
    if (this._previewConnected !== null) return false;
    const e = this._config.entities;
    const charging = this._state(e.charging_status);
    if (charging !== undefined) {
      const s = String(charging).toLowerCase();
      if (["charging", "on", "active", "running"].includes(s)) return true;
    }
    return false;
  }

  _isConnected() {
    if (this._previewConnected !== null) return this._previewConnected;
    const e = this._config.entities;
    const explicit = this._state(e.charging_connected);
    if (explicit !== undefined) return this._isTruthyState(explicit);

    const status = this._state(e.charging_connection_status);
    if (status !== undefined) return this._isTruthyState(status);

    const charging = this._state(e.charging_status);
    return this._isTruthyState(charging);
  }

  _lockState() {
    const lockEntity = this._entity(this._config.entities.lock);
    if (!lockEntity) return null;
    const s = String(lockEntity.state).toLowerCase();
    if (s === "locked") return "locked";
    if (s === "unlocked") return "unlocked";
    return s;
  }

  _powertrain() {
    const forced = String(this._config.powertrain || "auto").toLowerCase();
    if (["ev", "phev", "ice"].includes(forced)) return forced;

    const e = this._config.entities;
    const hasElectric = !!(e.battery || e.electric_range);
    const hasFuel = !!(e.fuel_level || e.fuel_range);
    if (hasElectric && hasFuel) return "phev";
    if (hasElectric) return "ev";
    return "ice";
  }

  _formatEntity(ref, fallbackUnit = "", decimals = null) {
    const entity = this._entity(ref);
    if (!entity || this._isUnavailableValue(entity.state)) {
      return { value: "—", unit: fallbackUnit, raw: null };
    }
    const raw = entity.state;
    const n = Number(raw);
    let value = raw;
    if (Number.isFinite(n) && decimals !== null) value = n.toFixed(decimals);
    else if (Number.isFinite(n)) value = Math.round(n).toString();
    const unit = entity.attributes?.unit_of_measurement ?? fallbackUnit ?? "";
    return { value, unit, raw };
  }

  _resolveImage(spec, defaultAttribute = null) {
    if (!spec) return "";

    if (typeof spec === "string") {
      if (/^(sensor|image|camera)\./.test(spec)) {
        const entity = this._entity(spec);
        if (entity) {
          const attr = defaultAttribute && entity.attributes?.[defaultAttribute];
          if (attr) return attr;
          const entityPicture = entity.attributes?.entity_picture;
          if (entityPicture) return entityPicture;
          if (!this._isUnavailableValue(entity.state) &&
              (String(entity.state).startsWith("/") || String(entity.state).startsWith("http"))) {
            return entity.state;
          }
        }
        return "";
      }
      return spec;
    }

    if (typeof spec === "object") {
      if (spec.url || spec.path) return spec.url || spec.path;
      if (spec.entity) {
        const entity = this._entity(spec.entity);
        const attrName = spec.attribute || defaultAttribute;
        const attr = attrName ? entity?.attributes?.[attrName] : null;
        if (attr) return attr;
        if (entity?.attributes?.entity_picture) return entity.attributes.entity_picture;
        if (entity && !this._isUnavailableValue(entity.state) &&
            (String(entity.state).startsWith("/") || String(entity.state).startsWith("http"))) {
          return entity.state;
        }
        return spec.fallback || "";
      }
    }

    return "";
  }

  _availableImages() {
    const i = this._config.images || {};
    const result = [];
    const keys = ["side", "rear", "front"];
    for (const key of keys) {
      const defaultAttr =
        key === "side" ? "exterior_side_left" :
        key === "rear" ? "exterior_back" :
        key === "front" ? "exterior_front" :
        key;
      const url = this._resolveImage(i[key], defaultAttr);
      if (url) result.push({ key, url });
    }

    // Backward-friendly aliases.
    if (!result.some(x => x.key === "side") && i.exterior_side_left) {
      const url = this._resolveImage(i.exterior_side_left, "exterior_side_left");
      if (url) result.push({ key: "side", url });
    }
    if (!result.some(x => x.key === "rear") && i.exterior_back) {
      const url = this._resolveImage(i.exterior_back, "exterior_back");
      if (url) result.push({ key: "rear", url });
    }

    return result;
  }

  _currentImage() {
    const available = this._availableImages();
    const fallback = this._resolveImage(this._config.images?.fallback);

    if (!available.length) return { key: "fallback", url: fallback };

    if (this._manualImageKey) {
      const manual = available.find(x => x.key === this._manualImageKey);
      if (manual) return manual;
    }

    const mode = String(this._config.display.image_mode || "auto").toLowerCase();
    if (mode !== "auto") {
      const selected = available.find(x => x.key === mode);
      if (selected) return selected;
    }

    if (this._isConnected()) {
      return available.find(x => x.key === "rear") ||
             available[0];
    }
    return available.find(x => x.key === "side") || available[0];
  }

  _checkSquareImage(url) {
    if (!url || this._imageChecks.has(url)) return;
    this._imageChecks.set(url, { state: "loading" });
    const probe = new Image();
    probe.onload = () => {
      const width = probe.naturalWidth;
      const height = probe.naturalHeight;
      this._imageChecks.set(url, {
        state: width > 0 && height > 0 && width === height ? "square" : "invalid",
        width,
        height,
      });
      if (this._config && this._currentImage().url === url) this._render(true);
    };
    probe.onerror = () => {
      this._imageChecks.set(url, { state: "error" });
      if (this._config && this._currentImage().url === url) this._render(true);
    };
    probe.src = url;
  }

  _cycleImage() {
    const images = this._availableImages();
    if (images.length < 2) return;
    const current = this._currentImage();
    const idx = images.findIndex(x => x.key === current.key);
    this._manualImageKey = images[(idx + 1) % images.length].key;
    this._render(true);
  }

  _vehicleTitle() {
    const v = this._config.vehicle;
    const parts = [];
    if (this._config.display.show_brand && v.make) parts.push(v.make);
    if (this._config.display.show_model && v.model) parts.push(v.model);
    return parts.join(" ") || v.name || "Car";
  }

  _vehicleSubtitle() {
    const v = this._config.vehicle;
    const parts = [];
    if (v.name && v.name !== v.model && v.name !== this._vehicleTitle()) parts.push(v.name);
    if (this._config.display.show_trim && v.trim) parts.push(v.trim);
    return parts.join(" • ");
  }

  _statusText() {
    const labels = this._config.labels;
    if (this._isCharging()) return labels.charging;
    if (this._isConnected()) return labels.connected;
    const lock = this._lockState();
    if (lock === "locked") return labels.locked;
    if (lock === "unlocked") return labels.unlocked;
    return labels.parked;
  }

  _statusIcon() {
    if (this._isCharging()) return "mdi:ev-station";
    if (this._isConnected()) return "mdi:power-plug";
    const lock = this._lockState();
    if (lock === "locked") return "mdi:lock";
    if (lock === "unlocked") return "mdi:lock-open-variant";
    return "mdi:car";
  }

  _primaryStat() {
    const e = this._config.entities;
    const p = this._powertrain();
    if (p !== "ice" && this._isConnected() && !this._isCharging()) {
      const battery = this._formatEntity(e.battery, "%");
      if (battery.raw !== null) return battery;
    }
    const distanceUnit = this._config.units.distance || "km";
    const electric = p === "ice" ? null : this._formatEntity(e.electric_range, distanceUnit);
    const fuel = p === "ev" ? null : this._formatEntity(e.fuel_range, distanceUnit);
    if (p === "phev" && electric?.raw !== null && fuel?.raw !== null) {
      const electricValue = Number(electric.raw);
      const fuelValue = Number(fuel.raw);
      if (Number.isFinite(electricValue) && Number.isFinite(fuelValue)) {
        return { value: String(Math.round(electricValue + fuelValue)), unit: distanceUnit };
      }
    }
    return electric?.raw !== null && electric ? electric : fuel?.raw !== null && fuel ? fuel :
      { value: "—", unit: distanceUnit };
  }

  _secondaryStats() {
    const e = this._config.entities;
    const p = this._powertrain();
    const stats = [];

    if ((p === "ev" || p === "phev") && e.electric_range) {
      const electric = this._formatEntity(e.electric_range, this._config.units.distance || "km");
      stats.push({ icon: "mdi:flash", label: this._config.labels.electric, ...electric });
    }
    if (p === "phev" && e.fuel_range) {
      const fuelRange = this._formatEntity(e.fuel_range, this._config.units.distance || "km");
      stats.push({ icon: "mdi:gas-station", label: this._config.labels.fuel, ...fuelRange });
    }
    if ((p === "ice" || p === "phev") && e.fuel_level) {
      const fuelLevel = this._formatEntity(e.fuel_level, "%");
      stats.push({ icon: "mdi:gas-station", label: this._config.labels.fuel, ...fuelLevel });
    }
    return stats.filter(s => s.raw !== null).slice(0, 2);
  }

  async _toggleLock() {
    if (this._previewConnected !== null) return;
    const ref = this._config.entities.lock;
    if (!ref || !this._hass) return;
    const state = this._lockState();
    try {
      if (state === "locked") {
        await this._hass.callService("lock", "unlock", { entity_id: ref });
      } else {
        await this._hass.callService("lock", "lock", { entity_id: ref });
      }
    } catch (err) {
      console.error("Universal Car Card lock action failed", err);
    }
  }

  _openMoreInfo(entityId) {
    if (!entityId) return;
    const ev = new CustomEvent("hass-more-info", {
      detail: { entityId },
      bubbles: true,
      composed: true,
    });
    this.dispatchEvent(ev);
  }

  _toggleDialog(force = null) {
    this._dialogOpen = force === null ? !this._dialogOpen : !!force;
    this._render(true);
  }

  _esc(value) {
    return String(value ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;")
      .replaceAll("'", "&#039;");
  }

  _mdi(icon, size = 22) {
    return `<ha-icon icon="${this._esc(icon)}" style="--mdc-icon-size:${size}px"></ha-icon>`;
  }

  _render(force = false) {
    if (!this.shadowRoot || !this._config) return;
    const signature = JSON.stringify({
      entities: this._hass ? Object.fromEntries(
        Object.values(this._config.entities).filter(v => typeof v === "string" && v.includes("."))
          .map(id => [id, [this._hass.states?.[id]?.state, this._hass.states?.[id]?.attributes]])
      ) : {},
      images: this._availableImages(),
      dialog: this._dialogOpen,
      image: this._manualImageKey,
      dark: this._hass?.themes?.darkMode,
    });
    if (!force && signature === this._lastRenderSignature) return;
    this._lastRenderSignature = signature;

    const c = this._config;
    const image = this._currentImage();
    this._checkSquareImage(image.url);
    const check = this._imageChecks.get(image.url);
    const hasImage = !!image.url && check?.state === "square";
    const main = this._primaryStat();
    const stats = this._secondaryStats();
    const lock = this._lockState();
    const title = this._vehicleTitle();
    const imageCount = this._availableImages().length;
    const { scale, x, y } = uccImagePosition(c.styles, image.key);
    const imageError = check?.state === "invalid"
      ? `Image must be square (${check.width} × ${check.height}).`
      : check?.state === "error" ? "Image could not be loaded." : "";
    // Transparent vehicle artwork inherits the Home Assistant card background.
    this.shadowRoot.innerHTML = `
      <style>
        @font-face {
          font-family: "Hedvig Letters Sans";
          src: url("${UCC_VOLVO_FONT}") format("woff2");
          font-weight: normal;
          font-display: swap;
        }
        :host { display: block; font-family: "Hedvig Letters Sans", sans-serif; }
        ha-card {
          position: relative; overflow: hidden; border-radius: 16px;
          background: var(--ha-card-background, var(--card-background-color, #fff));
          color: var(--primary-text-color);
        }
        .volvo-card {
          position: relative;
          width: 100%;
          aspect-ratio: 1 / 1;
          overflow: hidden;
          background: transparent;
          cursor: ${c.entities.lock && this._previewConnected === null ? "pointer" : "default"};
        }
        .car-image {
          position: absolute; inset: 0; z-index: 0;
          width: 100%; height: 100%; object-fit: cover;
          /* 100% moves one scaled image width or height. */
          transform: scale(${scale}) translate(${x}%, ${y}%); transform-origin: center;
          pointer-events: none; user-select: none;
        }
        .header { position: absolute; left: 13px; top: 13px; z-index: 2; max-width: 90%; pointer-events: none; }
        .vehicle-name { font-size: 12px; font-weight: 500; margin-bottom: 4px; opacity: .7; }
        .main-value { font-size: clamp(36px, 11vw, 51px); font-weight: 300; letter-spacing: -.07em; line-height: 1; white-space: nowrap; }
        .main-unit { margin-left: -4px; font-weight: 300; }
        .sub-row { display: flex; align-items: center; gap: 4px; white-space: nowrap; line-height: 1.35; }
        .sub-row ha-icon { --mdc-icon-size: 20px; flex: none; }
        .sub-value { font-size: 18px; font-weight: 400; }
        .sub-label { font-size: 18px; font-weight: 300; opacity: .65; }
        .sub-row-2 { margin-left: 3px; font-size: 16px; font-weight: 300; opacity: .65; }
        .status { position: absolute; left: 13px; bottom: 13px; z-index: 2; font-size: 24px; font-weight: 300; }
        .header, .status { color: var(--primary-text-color); }
        .image-error {
          position: absolute; left: 13px; right: 13px; bottom: 55px; z-index: 2;
          padding: 8px; border-radius: 6px; color: var(--primary-text-color);
          background: var(--ha-card-background, var(--card-background-color, #202125)); font-size: 13px;
        }
        .placeholder { position: absolute; top: 40%; right: 15%; opacity: .2; --mdc-icon-size: 110px; }
        .image-switcher {
          position: absolute; right: 12px; bottom: 12px; z-index: 3;
          display: ${this._previewConnected === null && c.display.show_image_switcher && imageCount > 1 ? "grid" : "none"};
          place-items: center; width: 36px; height: 36px; border: 0; border-radius: 50%;
          background: var(--ha-card-background, #333); color: var(--primary-text-color, #fff); cursor: pointer;
        }
        .actions-backdrop {
          position: fixed; inset: 0; z-index: 1000; display: ${this._previewConnected === null && this._dialogOpen ? "flex" : "none"};
          justify-content: center; align-items: center; background: rgba(0,0,0,.5);
        }
        .actions-panel { display: flex; gap: 16px; }
        .action {
          display: flex; flex-direction: column; align-items: center; justify-content: center;
          gap: 8px; width: 84px; height: 84px; border: 0; border-radius: 20px;
          color: var(--primary-text-color); background: var(--ha-card-background, var(--card-background-color, white));
          box-shadow: 0 4px 20px rgba(0,0,0,.3); font: 500 12px "Hedvig Letters Sans", sans-serif; cursor: pointer;
        }
        .action ha-icon { --mdc-icon-size: 28px; }
        button:focus-visible { outline: 2px solid var(--primary-color); }
      </style>
      <ha-card>
        <div class="volvo-card" id="vehicle">
          ${hasImage ? `<img class="car-image" src="${this._esc(image.url)}" alt="${this._esc(title)}">` :
            `<ha-icon class="placeholder" icon="mdi:car-side"></ha-icon>`}
          <div class="header">
            <div class="vehicle-name">${this._esc(title)}</div>
            <div class="main-value">${this._esc(main.value)}<span class="main-unit"> ${this._esc(main.unit)}</span></div>
            ${stats.map((s, index) => index === 0
              ? `<div class="sub-row">${this._mdi(s.icon, 20)}<span class="sub-value">${this._esc(s.value)}${s.unit ? ` ${this._esc(s.unit)}` : ""}</span><span class="sub-label">${this._esc(s.label)}</span></div>`
              : `<div class="sub-row-2">${this._esc(s.value)}${s.unit ? ` ${this._esc(s.unit)}` : ""} ${this._esc(s.label)}</div>`).join("")}
          </div>
          <div class="status">${this._esc(this._statusText())}</div>
          ${imageError ? `<div class="image-error" role="alert">${this._esc(imageError)}</div>` : ""}
          <button class="image-switcher" id="image-switcher" title="Switch view" aria-label="Switch view">${this._mdi("mdi:rotate-3d-variant", 18)}</button>
        </div>
        <div class="actions-backdrop" id="dialog-backdrop">
          <div class="actions-panel" id="dialog">
            ${c.entities.lock && this._previewConnected === null ? `<button class="action" id="lock-action">${this._mdi(lock === "locked" ? "mdi:lock-open-variant" : "mdi:lock", 28)}<span>${this._esc(lock === "locked" ? c.labels.unlock : c.labels.lock)}</span></button>` : ""}
          </div>
        </div>
      </ha-card>
    `;
    this._bindEvents();
  }

  _bindEvents() {
    const root = this.shadowRoot;
    root.getElementById("vehicle")?.addEventListener("click", () => {
      if (this._config.entities.lock && this._previewConnected === null) this._toggleDialog(true);
    });
    root.getElementById("image-switcher")?.addEventListener("click", ev => {
      ev.stopPropagation();
      this._cycleImage();
    });
    root.getElementById("dialog-backdrop")?.addEventListener("click", ev => {
      if (ev.target?.id === "dialog-backdrop") this._toggleDialog(false);
    });
    root.getElementById("dialog")?.addEventListener("click", ev => ev.stopPropagation());
    root.getElementById("lock-action")?.addEventListener("click", async ev => {
      ev.stopPropagation();
      await this._toggleLock();
      this._toggleDialog(false);
    });
  }
}

/**
 * Lightweight visual editor. It intentionally covers the settings that
 * typically change when swapping cars. Advanced options stay in YAML.
 */
class UniversalCarCardEditor extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._config = {};
    this._hass = null;
    this._previewCards = [];
    this._previewExpanded = false;
  }

  setConfig(config) {
    this._config = JSON.parse(JSON.stringify(config || {}));
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    for (const form of this.shadowRoot.querySelectorAll("ha-form")) {
      form.hass = hass;
    }
    for (const preview of this._previewCards) preview.hass = hass;
  }

  _get(path, fallback = "") {
    const parts = path.split(".");
    let cur = this._config;
    for (const p of parts) {
      if (!cur || typeof cur !== "object") return fallback;
      cur = cur[p];
    }
    return cur ?? fallback;
  }

  _set(path, value) {
    const parts = path.split(".");
    const cfg = JSON.parse(JSON.stringify(this._config || {}));
    let cur = cfg;
    for (let i = 0; i < parts.length - 1; i++) {
      if (!cur[parts[i]] || typeof cur[parts[i]] !== "object") cur[parts[i]] = {};
      cur = cur[parts[i]];
    }
    const key = parts[parts.length - 1];
    if (value === "") delete cur[key];
    else cur[key] = value;

    this._config = cfg;
    this._emitConfig(cfg);
    this._render();
  }

  _emitConfig(cfg) {
    this.dispatchEvent(new CustomEvent("config-changed", {
      detail: { config: cfg },
      bubbles: true,
      composed: true,
    }));
  }

  _entityFields() {
    return [
      ["battery", "Battery level", ["sensor", "number"]],
      ["electric_range", "Electric range", ["sensor", "number"]],
      ["fuel_level", "Fuel level", ["sensor", "number"]],
      ["fuel_range", "Fuel range", ["sensor", "number"]],
      ["charging_connected", "Plug connected", ["binary_sensor", "sensor", "switch"]],
      ["charging_connection_status", "Connection status", ["binary_sensor", "sensor"]],
      ["charging_status", "Charging status", ["sensor", "binary_sensor"]],
      ["lock", "Lock", ["lock"]],
      ["odometer", "Odometer", ["sensor", "number"]],
    ];
  }

  _entitiesChanged(ev) {
    ev.stopPropagation();
    const values = ev.detail?.value?.entities;
    if (!values || typeof values !== "object") return;
    const cfg = JSON.parse(JSON.stringify(this._config));
    cfg.entities = { ...(cfg.entities || {}) };
    for (const [key] of this._entityFields()) {
      const value = values[key];
      if (typeof value === "string" && value.trim()) cfg.entities[key] = value.trim();
      else delete cfg.entities[key];
    }
    this._config = cfg;
    this._emitConfig(cfg);
  }

  _imageSourceChanged(ev) {
    ev.stopPropagation();
    const values = ev.detail?.value?.image_source;
    if (!values || typeof values !== "object") return;
    const cfg = JSON.parse(JSON.stringify(this._config));
    cfg.images = { ...(cfg.images || {}) };
    for (const key of ["side", "rear"]) {
      const value = values[key];
      if (typeof value === "string" && value.trim()) cfg.images[key] = value.trim();
      else if (typeof cfg.images[key] === "string" &&
               /^(sensor|image)\./.test(cfg.images[key])) delete cfg.images[key];
    }
    this._config = cfg;
    this._emitConfig(cfg);
    this._render();
  }

  _esc(v) {
    return String(v ?? "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;")
      .replaceAll('"', "&quot;");
  }

  _render() {
    if (!this.shadowRoot) return;

    const textFields = [
      ["vehicle.make", "Make", "e.g. Volvo"],
      ["vehicle.model", "Model", "e.g. EX30"],
      ["vehicle.trim", "Trim", "e.g. Ultra"],
      ["images.side", "Side image URL", "/local/..."],
      ["images.rear", "Rear image URL", "/local/..."],
      ["images.fallback", "Fallback image URL", "/local/..."],
    ];
    const entityFields = this._entityFields();
    const labels = Object.fromEntries(entityFields.map(([key, label]) => [key, label]));
    const imageSource = {};
    for (const key of ["side", "rear"]) {
      const spec = this._get(`images.${key}`);
      if (typeof spec === "string" && /^(sensor|image)\./.test(spec)) imageSource[key] = spec;
    }
    const hasAdvancedImages = ["side", "rear"].some(key => {
      const spec = this._get(`images.${key}`);
      return spec && typeof spec === "object";
    });
    const imageControls = ["side", "rear"].map(key => ({
      key,
      title: key === "side" ? "Side image" : "Rear image",
      position: uccImagePosition(this._get("styles", {}), key),
    }));

    this.shadowRoot.innerHTML = `
      <style>
        :host { display:block; }
        .editor {
          display: grid;
          gap: 18px;
          padding: 4px 0;
        }
        .text-grid {
          display: grid;
          grid-template-columns: repeat(2, minmax(0,1fr));
          gap: 12px;
        }
        label {
          display:flex;
          flex-direction:column;
          gap:5px;
          color:var(--primary-text-color);
          font-size:12px;
        }
        input {
          box-sizing:border-box;
          width:100%;
          border:1px solid var(--divider-color);
          border-radius:8px;
          padding:10px;
          background:var(--card-background-color);
          color:var(--primary-text-color);
          font:inherit;
        }
        .image-controls { display: grid; gap: 14px; margin-top: 14px; }
        .image-control { min-width: 0; padding: 10px 12px; border: 1px solid var(--divider-color); border-radius: 8px; }
        .image-control legend { color: var(--primary-text-color); font-size: 14px; font-weight: 600; }
        .image-control label { margin: 8px 0; }
        .image-control input[type="range"] { padding: 0; border: 0; cursor: pointer; }
        .image-control .slider-label { display: flex; justify-content: space-between; }
        .hint, .advanced {
          color:var(--secondary-text-color);
          font-size:12px;
          line-height:1.4;
        }
        .advanced { grid-column: 1/-1; }
        details.preview-details { border-top: 1px solid var(--divider-color); padding-top: 12px; }
        details.preview-details summary { cursor: pointer; color: var(--primary-text-color); font-size: 14px; font-weight: 600; }
        .preview-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 12px; }
        .preview-item { min-width: 0; color: var(--secondary-text-color); font-size: 12px; }
        .preview-item universal-car-card { display: block; margin-top: 6px; }
        h3 { font-size:14px; margin:0 0 10px; }
        @media(max-width:650px) {
          .text-grid { grid-template-columns:1fr; }
          .preview-grid { grid-template-columns: 1fr; }
        }
      </style>
      <div class="editor">
        <div class="text-grid">
          ${textFields.slice(0, 3).map(([path, label, placeholder]) => `
            <label>${this._esc(label)}
              <input data-path="${this._esc(path)}" value="${this._esc(this._get(path))}" placeholder="${this._esc(placeholder)}">
            </label>
          `).join("")}
        </div>
        <section>
          <h3>Entities</h3>
          <div id="entity-form"></div>
        </section>
        <section>
          <h3>Images</h3>
          <div class="hint">Select an image entity or enter a URL. Source images must be square; the card checks their dimensions when loading.</div>
          <div id="image-source-form"></div>
          <div class="text-grid">
            ${textFields.slice(3).map(([path, label, placeholder]) => {
              const value = this._get(path);
              const advanced = value && typeof value === "object";
              return `<label>${this._esc(label)}
                <input data-path="${this._esc(path)}" value="${this._esc(advanced ? "" : value)}"
                  placeholder="${this._esc(advanced ? "Set in YAML" : placeholder)}"
                  ${advanced ? "disabled" : ""}>
              </label>`;
            }).join("")}
            ${hasAdvancedImages ? '<div class="advanced">An image uses an entity attribute configured in YAML. Edit it in the code editor.</div>' : ""}
          </div>
          <div class="image-controls">
            ${imageControls.map(({key, title, position}) => `
              <fieldset class="image-control">
                <legend>${title}</legend>
                <label>Scale (0.5–4)
                  <input type="number" data-position="${key}.scale" min="0.5" max="4" step="0.1" value="${position.scale}">
                </label>
                <label><span class="slider-label">Horizontal position <output id="position-${key}-x-value">${position.x}%</output></span>
                  <input type="range" data-position="${key}.x" min="-100" max="100" step="1" value="${position.x}">
                </label>
                <label><span class="slider-label">Vertical position <output id="position-${key}-y-value">${position.y}%</output></span>
                  <input type="range" data-position="${key}.y" min="-100" max="100" step="1" value="${position.y}">
                </label>
                <div class="hint">Positions are percentages of the displayed image width and height.</div>
              </fieldset>
            `).join("")}
          </div>
        </section>
        <details class="preview-details" id="preview-details" ${this._previewExpanded ? "open" : ""}>
          <summary>Preview: disconnected and connected</summary>
          <div class="preview-grid">
            <div class="preview-item">Disconnected<div id="preview-disconnected"></div></div>
            <div class="preview-item">Connected<div id="preview-connected"></div></div>
          </div>
          <p class="hint">Previews only; your vehicle state is not changed.</p>
        </details>
      </div>
    `;

    const entityForm = document.createElement("ha-form");
    entityForm.hass = this._hass;
    entityForm.schema = [{
      type: "grid", name: "entities", column_min_width: "220px",
      schema: entityFields.map(([name, , domain]) => ({
        name, selector: { entity: { domain } },
      })),
    }];
    entityForm.data = { entities: { ...(this._config.entities || {}) } };
    entityForm.computeLabel = schema => labels[schema.name] || undefined;
    entityForm.addEventListener("value-changed", ev => this._entitiesChanged(ev));
    this.shadowRoot.getElementById("entity-form").appendChild(entityForm);

    const sourceForm = document.createElement("ha-form");
    sourceForm.hass = this._hass;
    sourceForm.schema = [{
      type: "grid", name: "image_source", column_min_width: "220px",
      schema: ["side", "rear"].map(name => ({
        name, selector: { entity: { domain: ["sensor", "image"] } },
      })),
    }];
    sourceForm.data = { image_source: imageSource };
    sourceForm.computeLabel = schema =>
      ({ side: "Side image entity", rear: "Rear image entity" })[schema.name];
    sourceForm.addEventListener("value-changed", ev => this._imageSourceChanged(ev));
    this.shadowRoot.getElementById("image-source-form").appendChild(sourceForm);

    for (const input of this.shadowRoot.querySelectorAll("input[data-path]")) {
      input.addEventListener("change", () => {
        this._set(input.dataset.path, input.value.trim());
      });
    }
    for (const input of this.shadowRoot.querySelectorAll("input[data-position]")) {
      const [key, property] = input.dataset.position.split(".");
      if (property !== "scale") {
        const output = this.shadowRoot.getElementById(`position-${key}-${property}-value`);
        input.addEventListener("input", () => { output.textContent = `${input.value}%`; });
      }
      input.addEventListener("change", () => {
        const value = Number(input.value);
        if (!Number.isFinite(value) || input.value === "") return;
        const limit = property === "scale" ? [0.5, 4] : [-100, 100];
        this._set(`styles.${key}.${property}`, Math.min(limit[1], Math.max(limit[0], value)));
      });
    }
    const details = this.shadowRoot.getElementById("preview-details");
    details.addEventListener("toggle", () => { this._previewExpanded = details.open; });
    for (const [index, id] of ["preview-disconnected", "preview-connected"].entries()) {
      if (!this._previewCards[index]) {
        this._previewCards[index] = document.createElement("universal-car-card");
        this._previewCards[index].setPreviewConnected(index === 1);
      }
      const preview = this._previewCards[index];
      preview.setConfig(this._config);
      preview.hass = this._hass;
      this.shadowRoot.getElementById(id).appendChild(preview);
    }
  }
}

if (!customElements.get("universal-car-card")) {
  customElements.define("universal-car-card", UniversalCarCard);
}
if (!customElements.get("universal-car-card-editor")) {
  customElements.define("universal-car-card-editor", UniversalCarCardEditor);
}

window.customCards = window.customCards || [];
if (!window.customCards.some(card => card.type === "universal-car-card")) {
  window.customCards.push({
    type: "universal-car-card",
    name: "Universal Car Card",
    description: "Vehicle card for EV, plug-in hybrid, and combustion cars.",
    preview: true,
    documentationURL: "",
  });
}

console.info(
  `%c UNIVERSAL-CAR-CARD %c v${UCC_VERSION} `,
  "color:white;background:#3a6ea5;font-weight:700;",
  "color:#3a6ea5;background:#e9f1f9;"
);
